from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('P06','Dai campioni alla validazione spaziale','Vicinato, permutazioni e trasferimento verso un settore escluso')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('P06',i,b)
m.sezione_nuova('Geometria e osservazioni sintetiche')
p('La domanda collega struttura e trasferimento',
'''Il progetto utilizza sessantaquattro concentrazioni sintetiche collocate su un reticolo locale, per esaminare due problemi distinti: la presenza di associazione fra valori vicini e la capacità di prevedere un settore geografico escluso dall’adattamento. Il primo problema viene formulato attraverso un indice di Moran e un riferimento di permutazione; il secondo richiede previsioni confrontate con valori tenuti separati. Una struttura spaziale evidente può coesistere con errori elevati nel trasferimento, soprattutto quando il settore da prevedere supera il dominio osservato durante l’adattamento.''',tikz=d('D01',rect(.5,.5,6.9,1.8)+n(3.7,1.15,'Reticolo e concentrazioni sintetiche',w=6,size=11.5)+a(2,2,2,2.8)+a(5.4,2,5.4,2.8,'Quantum')+rect(.4,3,3.5,4.7)+n(1.95,3.85,'Associazione fra vicini',w=2.8,size=12)+rect(3.9,3,7,4.7,'Quantum')+n(5.45,3.85,'Previsione in un settore escluso',w=2.8,size=11.5)+n(3.7,5.6,'Due domande, due riferimenti di valutazione',w=6.8,size=11.5)),richiamo='Il test di associazione spaziale e la verifica predittiva sostengono conclusioni differenti.',origine='P06:1–4,17')
p('Le coordinate locali delimitano il significato metrico',
'''Le coordinate x e y variano da zero a 1750 metri con passo di 250 metri, formando otto righe e otto colonne. Le coordinate geografiche incluse nella tabella derivano invece da una costruzione approssimata, della quale va conservata la natura didattica. Le distanze del progetto vengono calcolate sul piano locale metrico, senza attribuirgli automaticamente un sistema UTM reale. Un intervallo numerico plausibile di longitudine e latitudine non certifica datum, accuratezza o provenienza delle posizioni.''',formula=r'd_{ij}=\sqrt{(x_i-x_j)^2+(y_i-y_j)^2}',destra='Il controllo verifica identificativi, coordinate finite e assenza di posizioni duplicate. Metadati di riferimento e protocollo di acquisizione sono informazioni ulteriori, che un’applicazione a osservazioni reali dovrebbe documentare prima di qualsiasi trasformazione cartografica.',richiamo='La distanza eredita le unità e le ipotesi geometriche del sistema di coordinate utilizzato.',origine='P06:3,5–7')
c=estratto('P06','coordinate',"d <- read.csv('dati/spazio_v3.csv')\nxy <- as.matrix(d[c('x_m','y_m')])\nstopifnot(nrow(d)==64,!anyDuplicated(d$id),\n all(is.finite(xy)),\n !anyDuplicated(paste(d$x_m,d$y_m)))\nD <- as.matrix(dist(xy))\nstopifnot(all(diag(D)==0),all(D==t(D)))")
p('La matrice delle distanze',
'''La matrice D riporta la distanza fra ogni coppia di punti e conserva una diagonale nulla, poiché ogni posizione coincide con sé stessa. La simmetria deriva dalla metrica euclidea, mentre l’assenza di duplicati rende distinti i siti. Questi controlli intercettano errori di costruzione prima che le distanze entrino nei pesi del test e dell’interpolazione. Il significato geologico delle posizioni resta comunque legato alla provenienza dichiarata, che in questo esercizio corrisponde a un dominio sintetico.''',codice=c,richiamo='Le proprietà della matrice verificano la geometria del calcolo e precedono l’interpretazione del campo.',origine='P06:5–7,9')
p('La carta conserva il supporto puntuale',
'''Ogni simbolo rappresenta il valore attribuito a un sito del reticolo, mentre il colore segue una scala comune di concentrazione in unità arbitrarie. Il rapporto unitario fra gli assi conserva le distanze e rende riconoscibile la disposizione dei punti. Gli spazi fra i simboli rimangono privi di un valore osservato: un’eventuale superficie continua richiederebbe un ulteriore modello di interpolazione. La carta descrive quindi la struttura disponibile senza attribuire automaticamente la misura puntuale a tutto il suo intorno.''',figura='P06/F01',didascalia='Sessantaquattro punti sintetici su un piano locale metrico. Colori: concentrazione in unità arbitrarie.',richiamo='Supporto della misura e geometria della rappresentazione devono rimanere riconoscibili nella carta.',origine='P06:8–10')
m.sezione_nuova('Vicinato e riferimento di permutazione')
p('La soglia di distanza definisce una rete di relazioni',
'''Due siti sono considerati vicini quando la loro distanza è positiva e non supera 260 metri. Su questo reticolo la regola include i contatti orizzontali e verticali, escludendo quelli diagonali. Si ottengono 112 legami non orientati, che compaiono due volte nella matrice simmetrica dei pesi. La soglia definisce la scala di associazione esaminata e non rappresenta una proprietà universale del processo. Cambiarla modificherebbe il riferimento geometrico dell’indice e richiederebbe una sensibilità dichiarata.''',formula=r'w_{ij}=\mathbf1\{0<d_{ij}\leq260\},\qquad S_0=\sum_i\sum_jw_{ij}=224',figura='P06/F02',didascalia='Vicinato binario: 112 legami non orientati.',richiamo='L’associazione spaziale viene definita rispetto a una specifica struttura di vicinato.',origine='P06:11–12')
p('L’indice confronta prodotti fra scarti vicini',
'''Centrando le concentrazioni rispetto alla media del reticolo, il prodotto fra due scarti è positivo quando entrambi si trovano dalla stessa parte della media. L’indice di Moran riunisce questi prodotti sui legami selezionati e li normalizza mediante dispersione e somma dei pesi. Nel caso osservato vale circa 0,71953. Il valore indica un’associazione positiva rispetto al vicinato binario adottato, mentre la sua interpretazione inferenziale richiede la costruzione di un riferimento coerente con le ipotesi di scambiabilità.''',formula=r'v_i=z_i-\overline z,\qquad I=\frac{n}{S_0}\frac{\sum_i\sum_jw_{ij}v_iv_j}{\sum_i v_i^2}',tikz=d('D02',rect(.6,1,3.2,2.7)+n(1.9,1.85,r'$v_i>0$',size=17)+rect(4.1,1,6.7,2.7)+n(5.4,1.85,r'$v_j>0$',size=17)+linea(3.2,1.85,4.1,1.85,'Quantum')+n(3.7,3.7,r'$w_{ij}v_iv_j>0$',size=17)+n(3.7,5.2,'Scarti concordi contribuiscono positivamente.',w=6.7,size=11.5)),richiamo='Segno e grandezza dell’indice dipendono da scarti, dispersione e pesi specificati.',origine='P06:11–13')
p('Le permutazioni conservano siti e valori marginali',
'''Il riferimento riassegna le concentrazioni alle posizioni fisse e ricalcola l’indice, conservando insieme dei valori e geometria. Questa operazione è pertinente sotto un’ipotesi di scambiabilità delle assegnazioni, che un gradiente spaziale sistematico può rendere scientificamente discutibile come modello nullo. Nel progetto vengono conservati 999 piani di permutazione, così che la distribuzione possa essere ricostruita anche senza ripetere il generatore casuale. L’esito riguarda il riferimento scelto e non identifica il meccanismo fisico che genera la struttura.''',tikz=d('D03',''.join(rect(.8+j*1.8,1,2.1+j*1.8,2.3)+n(1.45+j*1.8,1.65,str(k),size=16) for j,k in enumerate([12,18,24]))+a(3.25,2.7,3.25,3.4,'Quantum')+''.join(rect(.8+j*1.8,3.8,2.1+j*1.8,5.1,'Quantum')+n(1.45+j*1.8,4.45,str(k),size=16) for j,k in enumerate([24,12,18]))+n(3.7,5.9,'Stesse posizioni, nuova assegnazione dei valori',w=6.8,size=11)),richiamo='La distribuzione di permutazione deriva da un’ipotesi sulle assegnazioni ammissibili.',origine='P06:11–13')
p('Numero di permutazioni e risoluzione',
'''Nessuno dei 999 indici permutati raggiunge quello osservato nella coda positiva. Con la correzione più uno, la probabilità Monte Carlo è quindi 0,001, che coincide con il minimo rappresentabile da questa costruzione. I cento piani delle esercitazioni originarie avevano risoluzione 1/101; l’aumento delle repliche migliora la risoluzione numerica del riferimento, lasciando immutata l’informazione osservativa del reticolo. La conclusione riguarda l’incompatibilità con l’assegnazione scambiabile considerata, sotto le relative condizioni.''',formula=r'\widehat p=\frac{1+\sum_{b=1}^{999}\mathbf1\{I_b\geq I_{obs}\}}{1000}=0{,}001',figura='P06/F03',didascalia='Indice binario osservato in viola e distribuzione dei 999 indici permutati.',richiamo='La precisione Monte Carlo e la plausibilità scientifica del riferimento sono componenti distinte del test.',origine='P06:12–13')
m.sezione_nuova('Previsione e verifica nel settore orientale')
p('La geometria del settore escluso',
'''L’adattamento utilizza i quaranta siti con coordinata x inferiore a 1250 metri, mentre i ventiquattro siti rimanenti costituiscono il settore orientale di verifica. Il valore massimo di x nel train è mille metri, per cui il test oltrepassa la copertura osservata lungo quella direzione. Questa separazione rappresenta un trasferimento spaziale e richiede estrapolazione geografica rispetto ai siti disponibili. Una divisione casuale avrebbe spesso vicini di adattamento attorno ai punti di verifica e risponderebbe a una domanda differente.''',figura='P06/F04',didascalia='Verde: quaranta siti di adattamento; viola: ventiquattro siti orientali separati per la verifica.',richiamo='La geometria della separazione determina il tipo di generalizzazione che viene valutato.',origine='P06:14–16')
p('L’IDW costruisce una combinazione convessa locale',
'''La previsione usa pesi inversamente proporzionali al quadrato della distanza dai soli siti di adattamento, normalizzati affinché la loro somma sia uno. La previsione appartiene quindi all’intervallo dei valori disponibili nel train. Quando un gradiente prosegue oltre il settore osservato, questo vincolo può impedire di riprodurre valori più alti presenti nella fascia esclusa. Il calcolo del peso dipende soltanto dalla posizione del punto da prevedere e dai dati ammessi all’adattamento.''',formula=r'\lambda_i(s)=\frac{d(s,s_i)^{-2}}{\sum_{j\in train}d(s,s_j)^{-2}},\qquad \widehat z(s)=\sum_{i\in train}\lambda_i(s)z_i',tikz=d('D04',n(3.7,3,r'$s$',size=20,color='Quantum')+''.join(a(x,y,3.4,2.8)+n(x,y,str(i),size=13) for i,(x,y) in enumerate([(1,1),(6.3,1.2),(1.2,4.8),(6.2,4.6)],1))+n(3.7,5.8,r'$\lambda_i\geq0,\quad\sum_i\lambda_i=1$',w=6.6,size=15)),richiamo='La positività dei pesi limita la previsione ai valori osservati nei siti utilizzati.',origine='P06:14–15')
c=estratto('P06','IDW',"d <- read.csv('dati/spazio_v3.csv')\ntr <- d$x_m<1250\nq <- vapply(which(!tr),function(i){\n r <- sqrt((d$x_m[tr]-d$x_m[i])^2+\n           (d$y_m[tr]-d$y_m[i])^2)\n w <- r^-2\n sum(w*d$concentrazione[tr])/sum(w)\n},numeric(1))\ne <- d$concentrazione[!tr]-q\nc(MAE=mean(abs(e)),RMSE=sqrt(mean(e^2)))")
p('Il codice esclude le risposte del settore di verifica',
'''Il frammento percorre i siti orientali e costruisce per ciascuno le distanze dai soli quaranta siti di adattamento. Le concentrazioni orientali entrano soltanto nel calcolo finale degli errori, dopo che le previsioni sono state prodotte. La separazione viene verificata insieme alla finitezza dei risultati e all’appartenenza delle previsioni all’intervallo del train. Una funzione generale gestisce inoltre il caso di distanza nulla, restituendo il valore del sito coincidente; nella fascia esclusa questo caso non si presenta.''',codice=c,richiamo='La verifica indipendente richiede che i valori da prevedere siano esclusi dalla costruzione dei pesi e della risposta stimata.',origine='P06:15–16')
p('La carta degli errori conserva la loro localizzazione',
'''Gli errori sono definiti come osservato meno previsto, per cui un valore positivo indica sottostima. La carta mostra dove la previsione si discosti maggiormente dal campo sintetico, mantenendo visibili i siti di adattamento in grigio. La media degli errori è circa 3,175 unità arbitrarie, segnalando una sottostima complessiva nel settore orientale. La localizzazione aiuta a collegare questa direzione dello scarto al gradiente e al vincolo delle combinazioni convesse, anziché ridurre la diagnosi a un’unica misura aggregata.''',figura='P06/F05',didascalia='Errori osservato meno previsto nella fascia est. Scala divergente centrata sullo zero.',richiamo='La posizione e il segno degli errori possono spiegare limiti che una metrica aggregata nasconde.',origine='P06:16–18')
p('Gli errori vengono quantificati nella scala del campo',
'''La MAE sul settore orientale è circa 3,257 e la RMSE circa 3,808 unità arbitrarie. Il diagramma osservato–previsto adotta la stessa scala sui due assi e consente di riconoscere le sottostime rispetto alla bisettrice. Queste misure descrivono il trasferimento geografico fissato, mentre il piccolo valore del test di Moran riguarda l’associazione nel reticolo. I due risultati possono dunque coesistere senza contraddizione, poiché una struttura spaziale evidente non garantisce una buona estrapolazione da una parte del dominio.''',figura='P06/F06',didascalia='Confronto sui ventiquattro siti esclusi. La bisettrice rappresenta previsione esatta.',richiamo='L’associazione spaziale descritta e la capacità di trasferimento valutata rispondono a domande differenti.',origine='P06:16–17')
p('La sensibilità della potenza resta esplorativa',
'''Il confronto delle potenze uno, due e tre rende visibile come una maggiore enfasi sui siti vicini modifichi l’errore nella stessa fascia est. La regola principale rimane quella con potenza due, dichiarata prima della verifica. Se si scegliesse la potenza dopo aver confrontato questi errori, il settore orientale assumerebbe il ruolo di insieme di selezione e servirebbe una nuova area indipendente per la valutazione finale. La figura viene quindi utilizzata per comprendere il metodo e i limiti del disegno.''',figura='P06/F07',didascalia='Sensibilità descrittiva alla potenza IDW sugli stessi siti orientali; nessuna nuova verifica indipendente.',richiamo='Un campione utilizzato per scegliere un parametro cambia ruolo nel procedimento di validazione.',origine='P06:17–19')
p('Consegna: collegare geometria, test e trasferimento',
'''La relazione presenta audit metrico, carta dei punti, vicinato, indice con riferimento di permutazione, separazione geografica e mappa degli errori. L’esercizio richiede di spiegare perché un indice elevato possa accompagnarsi a sottostima nel settore orientale, richiamando gradiente e vincoli dei pesi. La conclusione conserva la natura sintetica del campo e indica quali nuove misure territoriali renderebbero più informativo il trasferimento. Codice, piani di permutazione e previsioni per sito permettono di ricostruire ciascun passaggio.''',destra='R/P06_figure.R integra le attività M11_N01, N07, N14 e N19. La revisione mantiene il vicinato originale e porta a 999 le permutazioni del macroprogetto; i laboratori conservano le proprie numerosità dichiarate. Le coordinate geografiche approssimate non trasformano il reticolo in un rilievo di campo.',richiamo='La relazione collega la conclusione al riferimento statistico e alla geometria effettivamente valutati.',fonti='Raccordo M11; documentazione sf sui sistemi di riferimento',origine='P06:18–20')
m.salva()
